#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# header and the other room's booking stay as they were
[ "$(cat "$t")" = "$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty')" ] || { echo "header or other booking changed"; fail=1; }
# not found: exit 1, message on stderr, nothing on stdout, file unchanged
before=$(cat "$t")
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message: $err"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$out" ] || { echo "not found wrote to stdout: $out"; fail=1; }
[ "$(cat "$t")" = "$before" ] || { echo "not found changed the file"; fail=1; }
# usage: exit 2, usage on stderr, nothing on stdout
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message: $err"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); [ -z "$out" ] || { echo "usage wrote to stdout: $out"; fail=1; }
# same date and start in another room: only the named room's booking goes
u=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$u"
out=$(BOOKINGS=$u bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cross-room cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cross-room cancel output: $out"; fail=1; }
[ "$(cat "$u")" = "$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz')" ] || { echo "cross-room cancel removed the wrong booking"; fail=1; }
rm -f "$t" "$u"; exit $fail

